def categorize_exercise_effectiveness(exercise_type, music_genre, intensity_level, repititions):
    exercises = {
        'running': 5,
        'stairs': 10,
        'lifting': 8,
        'yoga': 2,
        'cycling': 6
    }
    music_boost = {
        'rock': 3,
        'pop': 2,
        'hiphop': 4,
        'classical': 1
    }
    return exercises.get(exercise_type, 0) + music_boost.get(music_genre, 0) + (intensity_level * repititions)

